#include <bits/stdc++.h>

#define int long long
using namespace std;

vector < int > fenwick;
void update(int k, int tm, int sz) {
    for (; k <= sz; k += k & -k)
        fenwick[k] += tm;
}
int query(int k) {
    int temp = 0;
    for (; k > 0; k -= k & -k)
        temp += fenwick[k];
    return temp;
}

signed main() {
    int tt=1;
    cin>>tt;
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    while(tt--){
        int n;
        cin >> n;
        int total = 3 * n;
        multiset < int, greater < int >> ms;
        for (int i = 0; i < 3 * n; i++) {
            int val;
            cin >> val;
            ms.insert(val);
        }
        vector < int > v;
        for (auto x: ms)
            v.push_back(x);
        fenwick.assign(3 * n + 5,0);
        for (int i = 0; i < 3 * n; i++)
            update(i + 1, v[i], 3 * n);
        int mx = 0;
        for (int i = 0; i <= n; i++) {
            int lo = 0, hi = n - i;
            int b = 0;
            while (hi >= lo) {
                int mid = (lo + hi) / 2;
                if (mid == n - i) {
                    hi = mid - 1;
                    continue;
                }
                int temp1 = v[i +2*mid] + v[i +2*mid+ 1];
                int temp2 = 3ll*v[i+3*(n-i)-mid-1];
                if(temp1>temp2){
                    b=mid+1;
                    lo=mid+1;
                }
                else{
                    hi=mid-1;
                }
            }
            int b1=b;
            int c=n-i-b;
            int sum=6ll*query(i)+4ll*(query(i+2*b1)-query(i))+3ll*(query(i+2*b1+3*c)-query(i+2*b1));
            mx=max(mx,sum);
        }
        cout<<mx<<endl;
    }
}
